91	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
92	       BK7258_MBOX_BOX0_BIT) != 0)
93	    {
94	      bk7258_ap_mbox_ack(mbox);
95	    }
96	
97	  mbox[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
98	  mbox[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
99	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
100	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
101	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
102	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->state;
103	  __asm volatile ("dmb sy" ::: "memory");
104	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
105	  state->ap_to_cp_doorbells++;
106	  __asm volatile ("dsb sy; sev" ::: "memory");
107	}
