164	static int bk7258_ap_validate_secondary_bootstrap(void)
165	{
166	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
167	    bk7258_cpu2_probe_state();
168	#ifdef CONFIG_BK7258_AP_IPI
169	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
170	#endif
171	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
172	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
173	#endif
174	
175	  __asm volatile ("dmb sy" ::: "memory");
176	
177	  if (cpu2->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
178	      cpu2->version != BK7258_CPU2_PROBE_STATE_VERSION ||
179	      cpu2->size != sizeof(struct bk7258_cpu2_probe_state_s) ||
180	      cpu2->generation != bk7258_ap_boot_state()->generation ||
181	      cpu2->state != BK7258_CPU2_EXPECTED_STATE ||
182	      cpu2->error != BK7258_CPU2_PROBE_ERROR_NONE ||
183	      cpu2->secondary_ready != 1 ||
184	      cpu2->online_mask != BK7258_CPU2_EXPECTED_MASK ||
185	      cpu2->local_core_id != 1 ||
186	      cpu2->physical_core_id != 2 ||
187	      cpu2->runtime_vtor != cpu2->vector ||
188	      cpu2->runtime_msp <= BK7258_CPU2_BOOT_STACK_BASE ||
189	      cpu2->runtime_msp > BK7258_CPU2_BOOT_STACK_TOP ||
190	      cpu2->idle_stack_base < BK7258_AP_RAM_BASE ||
191	      cpu2->idle_stack_base >= cpu2->idle_stack_top ||
192	      cpu2->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
193	    {
194	      return BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
195	    }
196	
197	#ifdef CONFIG_BK7258_AP_IPI
198	  if (ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
199	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
200	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
201	      ipi->generation != bk7258_ap_boot_state()->generation ||
202	      ipi->state != BK7258_AP_IPI_STATE_READY ||
203	      ipi->error != BK7258_AP_IPI_ERROR_NONE)
204	    {
205	      return BK7258_AP_ERROR_CPU2_IPI;
206	    }
207	#endif
208	
209	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
210	  if (smp->magic != BK7258_AP_SMP_STATE_MAGIC ||
211	      smp->version != BK7258_AP_SMP_STATE_VERSION ||
212	      smp->size != sizeof(struct bk7258_ap_smp_state_s) ||
213	      smp->generation != bk7258_ap_boot_state()->generation ||
214	      smp->state != BK7258_AP_SMP_STATE_ONLINE ||
215	      smp->error != BK7258_AP_SMP_ERROR_NONE ||
216	      smp->online_mask != BK7258_CPU2_EXPECTED_MASK)
217	    {
218	      return BK7258_AP_ERROR_CPU2_SMP_SCHEDULER;
219	    }
220	#endif
221	
222	  return BK7258_AP_ERROR_NONE;
223	}
224	#endif
