230	int bk7258_ap_main(int argc, char *argv[])
231	{
232	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
233	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
234	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
235	#endif
236	  uint32_t event;
237	  int error;
238	  int ret;
239	
240	  (void)argc;
241	  (void)argv;
242	
243	  if (state->magic != BK7258_AP_BOOT_STATE_MAGIC ||
244	      state->version != BK7258_AP_BOOT_STATE_VERSION ||
245	      state->size != sizeof(struct bk7258_ap_boot_state_s))
246	    {
247	      state->state = BK7258_AP_STATE_FAILED;
248	      state->error = BK7258_AP_ERROR_BAD_BOOT_STATE;
249	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
250	      goto parked;
251	    }
252	
253	  error = bk7258_ap_validate_runtime();
254	  if (error != BK7258_AP_ERROR_NONE)
255	    {
256	      state->state = BK7258_AP_STATE_FAILED;
257	      state->error = (uint32_t)error;
258	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
259	      goto parked;
260	    }
261	
262	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
263	  error = bk7258_ap_validate_secondary_bootstrap();
264	  if (error != BK7258_AP_ERROR_NONE)
265	    {
266	      state->state = BK7258_AP_STATE_FAILED;
267	      state->error = (uint32_t)error;
268	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
269	      goto parked;
270	    }
271	#else
272	  ret = bk7258_cpu2_probe_start(BK7258_CPU2_PROBE_TIMEOUT_MS);
273	  if (ret < 0)
274	    {
275	      state->state = BK7258_AP_STATE_FAILED;
276	      state->error = BK7258_AP_ERROR_CPU2_PROBE;
277	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
278	      goto parked;
279	    }
280	#endif
281	
282	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
283	  ret = bk7258_ap_smp_scheduler_selftest(
284	    BK7258_AP_SMP_DEFAULT_TIMEOUT_MS);
285	  if (ret < 0)
286	    {
287	      state->state = BK7258_AP_STATE_FAILED;
288	      state->error = BK7258_AP_ERROR_CPU2_SMP_SCHEDULER;
289	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
290	      goto parked;
291	    }
292	#endif
293	
294	  state->error      = BK7258_AP_ERROR_NONE;
295	  state->last_event = BK7258_AP_EVENT_READY;
296	  state->state      = BK7258_AP_STATE_READY;
297	  __asm volatile ("dmb sy" ::: "memory");
298	  bk7258_ap_mbox_send(BK7258_AP_EVENT_READY);
299	
300	  for (; ; )
301	    {
302	      event = bk7258_ap_mbox_receive();
303	      if (event != BK7258_AP_EVENT_NONE)
304	        {
305	          state->last_event = event;
306	        }
307	
308	      if (event == BK7258_AP_EVENT_STOP ||
309	          state->command == BK7258_AP_COMMAND_STOP)
310	        {
311	          state->state = BK7258_AP_STATE_STOPPING;
312	          __asm volatile ("dmb sy" ::: "memory");
313	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
314	          ret = bk7258_ap_smp_secondary_stop(
315	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
316	#else
317	          ret = bk7258_cpu2_probe_stop(
318	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
319	#endif
320	          if (ret < 0)
321	            {
322	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
323	              state->error = BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
324	#else
325	              state->error = BK7258_AP_ERROR_CPU2_PROBE;
326	#endif
327	              state->state = BK7258_AP_STATE_FAILED;
328	              state->last_event = BK7258_AP_EVENT_FAILED;
329	              bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
330	              break;
331	            }
332	
333	          state->state = BK7258_AP_STATE_STOPPED;
334	          state->last_event = BK7258_AP_EVENT_STOPPED;
335	          bk7258_ap_mbox_send(BK7258_AP_EVENT_STOPPED);
336	          break;
337	        }
338	
339	#ifdef CONFIG_BK7258_AP_IPI
340	      if (event == BK7258_AP_EVENT_IPI_TEST ||
341	          state->command == BK7258_AP_COMMAND_IPI_TEST)
342	        {
343	          volatile struct bk7258_ap_ipi_state_s *ipi =
344	            bk7258_ap_ipi_state();
345	
346	          state->command = BK7258_AP_COMMAND_NONE;
347	          __asm volatile ("dmb sy" ::: "memory");
348	          ret = bk7258_ap_ipi_selftest(ipi->requested_count,
349	                                       ipi->timeout_ms);
350	          if (ret < 0)
351	            {
352	              state->error = BK7258_AP_ERROR_CPU2_IPI;
353	              state->last_event = BK7258_AP_EVENT_IPI_TEST_FAILED;
354	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_FAILED);
