358	              state->error = BK7258_AP_ERROR_NONE;
359	              state->last_event = BK7258_AP_EVENT_IPI_TEST_PASSED;
360	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_PASSED);

280	  BK7258_AP_IPI_ERROR_BAD_COMMAND,
281	  BK7258_AP_IPI_ERROR_SEND,
282	  BK7258_AP_IPI_ERROR_TIMEOUT,
283	  BK7258_AP_IPI_ERROR_COUNT_MISMATCH,
