298	static void __attribute__((noinline, noreturn, used))
299	bk7258_ap_secondary_bootstrap(void)
300	{
301	  volatile struct bk7258_cpu2_probe_state_s *state;
302	
303	  bk7258_cpu2_fpu_initialize();
304	  state = bk7258_cpu2_probe_state();
305	  uint32_t control;
306	  uint32_t msp;
307	
308	  __asm volatile ("mrs %0, msp" : "=r" (msp));
309	  __asm volatile ("mrs %0, control" : "=r" (control));
310	
311	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
312	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
313	  state->runtime_vtor = BK7258_SCB_VTOR;
314	  state->runtime_msp = msp;
315	  state->control = control;
316	  state->boot_count++;
317	  __asm volatile ("dmb sy" ::: "memory");
318	
319	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
320	      state->version != BK7258_CPU2_PROBE_STATE_VERSION ||
321	      state->size != sizeof(struct bk7258_cpu2_probe_state_s))
322	    {
323	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
324	      goto parked;
325	    }
326	
327	  state->state = BK7258_CPU2_PROBE_STATE_BOOTSTRAP;
328	  __asm volatile ("dmb sy" ::: "memory");
329	
330	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR !=
331	        BK7258_CPU2_LOCAL_CORE_ID ||
332	      state->physical_core_id != BK7258_CPU2_PHYSICAL_ID)
333	    {
334	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_CORE_ID);
335	      goto parked;
336	    }
337	
338	  if (state->runtime_vtor !=
339	      (uint32_t)(uintptr_t)__vector_core1_table)
340	    {
341	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_VTOR);
342	      goto parked;
343	    }
344	
345	  if (msp <= BK7258_CPU2_BOOT_STACK_BASE ||
346	      msp > BK7258_CPU2_BOOT_STACK_TOP)
347	    {
348	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_MSP);
349	      goto parked;
350	    }
351	
352	  if (state->idle_stack_base < BK7258_AP_RAM_BASE ||
353	      state->idle_stack_base >= state->idle_stack_top ||
354	      state->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
355	    {
356	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
357	      goto parked;
358	    }
359	
360	#ifdef CONFIG_BK7258_AP_IPI
361	  if (bk7258_ap_ipi_secondary_initialize() < 0)
362	    {
363	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
364	      goto parked;
365	    }
366	#endif
367	
368	  state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
369	  state->error = BK7258_CPU2_PROBE_ERROR_NONE;
370	  state->online_mask = BK7258_AP_PRIMARY_MASK;
371	
372	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
373	  state->secondary_ready = 0;
374	  __asm volatile ("dmb sy" ::: "memory");
375	
376	  if (bk7258_cpu2_scheduler_irq_initialize() < 0)
377	    {
378	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
379	      goto parked;
380	    }
381	
382	  bk7258_ap_secondary_enter_scheduler(state->idle_stack_top);
383	#else
384	  state->secondary_ready = 1;
385	  __asm volatile ("dmb sy" ::: "memory");
386	  state->state = BK7258_CPU2_PROBE_STATE_SECONDARY_READY;
387	  __asm volatile ("dmb sy; sev" ::: "memory");
388	
389	#  ifdef CONFIG_BK7258_AP_IPI
390	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
391	#  endif
392	
393	  for (; ; )
394	    {
395	      __asm volatile ("dmb sy" ::: "memory");
396	      if (state->command == BK7258_CPU2_PROBE_COMMAND_STOP)
397	        {
398	          state->state = BK7258_CPU2_PROBE_STATE_STOPPING;
399	          state->secondary_ready = 0;
400	          __asm volatile ("dmb sy" ::: "memory");
401	          state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
402	          state->state = BK7258_CPU2_PROBE_STATE_STOPPED;
403	          __asm volatile ("dmb sy; sev" ::: "memory");
404	          goto parked;
405	        }
406	
407	      state->heartbeat++;
408	#  ifdef CONFIG_BK7258_AP_IPI
409	      __asm volatile ("dmb sy; dsb sy; wfi" ::: "memory");
410	#  else
411	      __asm volatile ("dmb sy; wfe" ::: "memory");
412	#  endif
413	    }
414	#endif
415	
416	parked:
417	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
418	  for (; ; )
419	    {
420	      __asm volatile ("wfe");
421	    }
422	}
