428	    (
429	      "cpsid i\n"
430	      "movs r0, #0\n"
431	      "msr control, r0\n"
432	      "msr basepri, r0\n"
433	      "msr faultmask, r0\n"
434	      "ldr r0, =0x20000000\n"
435	      "movs r1, #1\n"
436	      "str r1, [r0]\n"
