446	static void __attribute__((noinline, noreturn, used))
447	bk7258_ap_secondary_fault_handler(uint32_t *stack, uint32_t exception)
448	{
449	  volatile struct bk7258_cpu2_probe_state_s *state =
450	    bk7258_cpu2_probe_state();
451	  uintptr_t frame = (uintptr_t)stack;
452	  uint32_t error;
453	
454	  state->fault_exception = exception;
455	  state->fault_hfsr = BK7258_SCB_HFSR;
456	  state->fault_cfsr = BK7258_SCB_CFSR;
457	  state->fault_lr = BK7258_CPU2_INVALID_VALUE;
458	  state->fault_pc = BK7258_CPU2_INVALID_VALUE;
459	  state->fault_xpsr = BK7258_CPU2_INVALID_VALUE;
460	
461	  if ((frame & (sizeof(uint32_t) - 1u)) == 0 &&
462	      ((frame >= BK7258_CPU2_BOOT_STACK_BASE &&
463	        frame <= BK7258_CPU2_BOOT_STACK_TOP -
464	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
465	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
466	       ||
467	       (frame >= state->idle_stack_base &&
468	        frame <= state->idle_stack_top -
469	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
470	#endif
471	      ))
472	    {
473	      const volatile uint32_t *regs =
474	        (const volatile uint32_t *)frame;
475	
476	      state->fault_lr = regs[5];
477	      state->fault_pc = regs[6];
478	      state->fault_xpsr = regs[7];
479	    }
480	
481	  error = exception == 2u ?
482	    BK7258_CPU2_PROBE_ERROR_NMI :
483	    BK7258_CPU2_PROBE_ERROR_HARDFAULT;
484	  bk7258_cpu2_fail(error);
485	
486	  for (; ; )
487	    {
488	      __asm volatile ("wfe");
489	    }
490	}
