496	    (
497	      "tst lr, #4\n"
498	      "ite eq\n"
499	      "mrseq r0, msp\n"
500	      "mrsne r0, psp\n"
501	      "mrs r1, ipsr\n"
502	      "b bk7258_ap_secondary_fault_handler\n"
503	    );
