815	int bk7258_ap_smp_secondary_stop(uint32_t timeout_ms)
816	{
817	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
818	  (void)timeout_ms;
819	  return -ENOTSUP;
820	#else
821	  volatile struct bk7258_cpu2_probe_state_s *state =
822	    bk7258_cpu2_probe_state();
823	  int ret = OK;
824	
825	  if (timeout_ms == 0)
826	    {
827	      timeout_ms = BK7258_CPU2_PROBE_STOP_TIMEOUT_MS;
828	    }
829	
830	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
831	      state->version != BK7258_CPU2_PROBE_STATE_VERSION)
832	    {
833	      ret = -EIO;
834	    }
835	  else if (state->state == BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
836	           state->state == BK7258_CPU2_PROBE_STATE_BOOTSTRAP ||
837	           state->state == BK7258_CPU2_PROBE_STATE_STARTING)
838	    {
839	      state->command = BK7258_CPU2_PROBE_COMMAND_STOP;
840	      __asm volatile ("dmb sy" ::: "memory");
841	#ifdef CONFIG_BK7258_AP_IPI
842	      ret = bk7258_ap_ipi_wake_secondary();
843	      if (ret >= 0)
844	        {
845	          ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
846	                                 timeout_ms);
847	        }
848	#else
849	      __asm volatile ("sev" ::: "memory");
850	      ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
851	                             timeout_ms);
852	#endif
853	    }
854	  else if (state->state == BK7258_CPU2_PROBE_STATE_FAILED)
855	    {
856	      ret = -EIO;
857	    }
858	
859	  bk7258_cpu2_hold_reset(state);
860	  state->secondary_ready = 0;
861	  __asm volatile ("dmb sy" ::: "memory");
862	
863	#ifdef CONFIG_BK7258_AP_IPI
864	  if (ret >= 0)
865	    {
866	      bk7258_ap_ipi_mark_stopped();
867	    }
868	#endif
869	
870	  if (ret < 0 && state->state != BK7258_CPU2_PROBE_STATE_FAILED)
871	    {
872	      bk7258_cpu2_fail(ret == -ETIMEDOUT ?
873	        BK7258_CPU2_PROBE_ERROR_TIMEOUT :
874	        BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
875	    }
876	
877	  return ret;
878	#endif
879	}
