120	static uint32_t apctl_u32(const char *value, uint32_t fallback)
121	{
122	  char *end;
123	  unsigned long parsed;
124	
125	  if (value == NULL)
126	    {
127	      return fallback;
128	    }
129	
130	  parsed = strtoul(value, &end, 0);
131	  if (*value == '\0' || *end != '\0' || parsed > UINT32_MAX)
132	    {
133	      return fallback;
134	    }
135	
136	  return (uint32_t)parsed;
137	}
