139	static void apctl_status(void)
140	{
141	  struct bk7258_ap_boot_state_s state;
142	  struct bk7258_cpu2_probe_state_s cpu2;
143	  struct bk7258_ap_ipi_state_s ipi;
144	  struct bk7258_ap_smp_state_s smp;
145	  volatile struct bk7258_cpu2_probe_state_s *shared_cpu2 =
146	    bk7258_cpu2_probe_state();
147	  volatile struct bk7258_ap_ipi_state_s *shared_ipi =
148	    bk7258_ap_ipi_state();
