150	    bk7258_ap_smp_state();
151	
152	  bk7258_ap_get_status(&state);
153	  __asm volatile ("dmb sy" ::: "memory");
154	  memcpy(&cpu2, (const void *)(uintptr_t)shared_cpu2, sizeof(cpu2));
155	  memcpy(&ipi, (const void *)(uintptr_t)shared_ipi, sizeof(ipi));
156	  memcpy(&smp, (const void *)(uintptr_t)shared_smp, sizeof(smp));
157	  __asm volatile ("dmb sy" ::: "memory");
158	  printf("AP state=%s(%" PRIu32 ") error=%" PRIu32
159	         " generation=%" PRIu32 " heartbeat=%" PRIu32 "\n",
160	         apctl_state_name(state.state), state.state, state.error,
161	         state.generation, state.heartbeat);
162	  printf("AP core local=%" PRIu32 " physical=%" PRIu32
163	         " VTOR(init/run)=%08" PRIx32 "/%08" PRIx32
164	         " MSP(init/run)=%08" PRIx32 "/%08" PRIx32 "\n",
165	         state.local_core_id, state.physical_core_id,
166	         state.initial_vtor, state.runtime_vtor,
167	         state.initial_msp, state.runtime_msp);
168	  printf("AP clock=%" PRIu32 " SysTick ctrl/load/current=%08" PRIx32
169	         "/%08" PRIx32 "/%08" PRIx32 "\n",
170	         state.clock_hz, state.systick_ctrl,
171	         state.systick_reload, state.systick_current);
172	  printf("AP heap=%08" PRIx32 "..%08" PRIx32
173	         " test=%08" PRIx32 " doorbells cp/ap=%" PRIu32 "/%" PRIu32
174	         "\n", state.heap_start, state.heap_end, state.heap_test,
175	         state.cp_to_ap_doorbells, state.ap_to_cp_doorbells);
176	
177	  if (cpu2.magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
178	      cpu2.version == BK7258_CPU2_PROBE_STATE_VERSION &&
179	      cpu2.size == sizeof(cpu2))
180	    {
181	      printf("CPU2 state=%s(%" PRIu32 ") error=%" PRIu32
182	             " generation=%" PRIu32 " heartbeat=%" PRIu32 "\n",
183	             apctl_cpu2_state_name(cpu2.state), cpu2.state, cpu2.error,
184	             cpu2.generation, cpu2.heartbeat);
185	      printf("CPU2 core local=%" PRIu32 " physical=%" PRIu32
186	             " vector=%08" PRIx32 " VTOR=%08" PRIx32
187	             " MSP(init/run)=%08" PRIx32 "/%08" PRIx32 "\n",
188	             cpu2.local_core_id, cpu2.physical_core_id, cpu2.vector,
189	             cpu2.runtime_vtor, cpu2.initial_msp, cpu2.runtime_msp);
190	      printf("CPU2 control=%08" PRIx32
191	             " SYS(before/after)=%08" PRIx32 "/%08" PRIx32 "\n",
192	             cpu2.control, cpu2.control_before, cpu2.control_after);
193	
194	      if (cpu2.secondary_entry != 0 || cpu2.secondary_ready != 0 ||
195	          cpu2.idle_stack_base != 0 || cpu2.idle_stack_top != 0)
196	        {
197	          printf("CPU2 bootstrap entry=%08" PRIx32
198	                 " idle=%08" PRIx32 "..%08" PRIx32
199	                 " ready=%" PRIu32 " online=%08" PRIx32
200	                 " calls=%" PRIu32 " boots=%" PRIu32 "\n",
201	                 cpu2.secondary_entry, cpu2.idle_stack_base,
202	                 cpu2.idle_stack_top, cpu2.secondary_ready,
203	                 cpu2.online_mask, cpu2.smp_call_requests,
204	                 cpu2.boot_count);
205	        }
206	
207	      if (cpu2.fault_exception != 0)
208	        {
209	          printf("CPU2 fault exception=%" PRIu32
210	                 " HFSR/CFSR=%08" PRIx32 "/%08" PRIx32
211	                 " PC/LR/xPSR=%08" PRIx32 "/%08" PRIx32
212	                 "/%08" PRIx32 "\n",
213	                 cpu2.fault_exception, cpu2.fault_hfsr,
214	                 cpu2.fault_cfsr, cpu2.fault_pc, cpu2.fault_lr,
215	                 cpu2.fault_xpsr);
216	        }
217	    }
218	  else
219	    {
220	      printf("CPU2 state unavailable magic/version/size=%08" PRIx32
221	             "/%" PRIu32 "/%" PRIu32 "\n",
222	             cpu2.magic, cpu2.version, cpu2.size);
223	    }
224	
225	  if (ipi.magic == BK7258_AP_IPI_STATE_MAGIC &&
