247	             " dup/lost/fail=%" PRIu32 "/%" PRIu32 "/%" PRIu32
248	             "\n", ipi.tx_count[1], ipi.rx_count[1], pending10,
249	             ipi.last_tx_sequence[1], ipi.last_rx_sequence[1],
250	             ipi.duplicate_count[1], ipi.lost_count[1],
251	             ipi.send_failures[1]);
252	      printf("IPI irq/wake cpu0=%" PRIu32 "/%" PRIu32
253	             " cpu1=%" PRIu32 "/%" PRIu32
254	             " stale/spurious=%" PRIu32 "/%" PRIu32 "\n",
