91	static void bk7258_ap_mbox_send(uint32_t event)
92	{
93	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
94	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
95	
96	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
97	       BK7258_MBOX_BOX0_BIT) != 0)
98	    {
99	      bk7258_ap_mbox_ack(mbox);
100	    }
101	
102	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
103	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
104	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
105	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->command;
106	  __asm volatile ("dmb sy" ::: "memory");
107	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
108	  state->cp_to_ap_doorbells++;
109	  __asm volatile ("dsb sy; sev" ::: "memory");
