112	static uint32_t bk7258_ap_mbox_receive(void)
113	{
114	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
115	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
116	  uint32_t event = BK7258_AP_EVENT_NONE;
117	
118	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
119	       BK7258_MBOX_BOX0_BIT) != 0)
120	    {
121	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
122	          BK7258_AP_DOORBELL_MAGIC &&
123	          mbox[BK7258_MBOX_PARAM2_OFFSET / 4] == state->generation)
124	        {
125	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
126	        }
127	
128	      bk7258_ap_mbox_ack(mbox);
129	    }
130	
131	  return event;
132	}
