179	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
180	{
181	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
182	  uint32_t elapsed;
183	  uint32_t event;
184	
185	  if (timeout_ms == 0)
186	    {
187	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
188	    }
189	
190	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
191	    {
192	      event = bk7258_ap_mbox_receive();
193	      if (event != BK7258_AP_EVENT_NONE)
194	        {
195	          state->last_event = event;
196	        }
197	
198	      __asm volatile ("dmb sy" ::: "memory");
199	      if (state->state == wanted)
200	        {
201	          return OK;
202	        }
203	
204	      if (state->state == BK7258_AP_STATE_FAILED)
205	        {
206	          return -EIO;
207	        }
208	
209	      nxsig_usleep(1000);
210	    }

